# Reverse lookup: Bitunix symbol -> base symbol (e.g. "1000PEPEUSDT" -> "PEPE")
_REVERSE_LOOKUP = {v["symbol"]: k for k, v in BITUNIX_ALL_PAIRS.items()}


def get_pair_info(base_symbol: str) -> dict | None:
    """Look up pair info by base symbol (e.g. "BTC", "DOGE")."""
    return BITUNIX_ALL_PAIRS.get(base_symbol.upper())


def is_valid_pair(base_symbol: str) -> bool:
    """Check if a base symbol has an active USDT futures pair on Bitunix."""
    return base_symbol.upper() in BITUNIX_ALL_PAIRS


def get_bitunix_symbol(base_symbol: str) -> str | None:
    """Get the full Bitunix symbol (e.g. "BTCUSDT") for a base symbol."""
    info = BITUNIX_ALL_PAIRS.get(base_symbol.upper())
    return info["symbol"] if info else None


def get_base_symbol(bitunix_symbol: str) -> str:
    """Reverse lookup: Bitunix symbol -> base symbol.

    e.g. "1000PEPEUSDT" -> "PEPE", "BTCUSDT" -> "BTC"
    Falls back to stripping USDT if not found.
    """
    return _REVERSE_LOOKUP.get(bitunix_symbol, bitunix_symbol.replace("USDT", ""))

